import{z as o,x as s,o as i,c as d,q as B,j as l,D as a,d as t,s as r,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"欧洲 MiFID 体系","description":"","frontmatter":{"title":"欧洲 MiFID 体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-eu-mifid.md","filePath":"quant/gm-eu-mifid.md","lastUpdated":1791063341000}'),p={name:"quant/gm-eu-mifid.md"};function D(m,E,u,F,h,c){const A=s("Mermaid");return i(),d("div",null,[E[2]||(E[2]=B('<h1 id="欧洲-mifid-体系" tabindex="-1">欧洲 MiFID 体系 <a class="header-anchor" href="#欧洲-mifid-体系" aria-label="Permalink to &quot;欧洲 MiFID 体系&quot;">​</a></h1><div class="epigraph"><p>美国用一条机械规则保护订单，欧洲把同一组问题交给行为义务：交易所在透明度上竞争，中介为「足够步骤」的执行负责——读欧洲先读义务与豁免，再读簿。</p><footer>—— 据 MiFID II / MiFIR 公开文本；Foucault, Pagano and Röell, Market Liquidity, 2013 整理</footer></div><p><a href="/quant/gm-us-structure">上一课</a>把美国收成「订单保护加费用竞争」的系统：Reg NMS 用机械规则把分散报价拼成 NBBO。欧洲刻意不这么做：没有跨场所的 trade-through 禁令，也没有长期可用的单一磁带；多场所竞争照样存在，但秩序由另一组工具维持——场所分类、透明度义务与豁免、中介的最佳执行义务。本课写这套体系的结构与对策略的含义，衔接方式沿用上一课的清单法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧洲股权交易同样分散在受监管市场（RM）、多边交易设施（MTF）与系统性内部化者（SI）之间，缺口的起点是一个义务而非一条规则：中介为客户执行时要采取「一切足够步骤」争取最优结果。这个义务不指定场所，于是「最优」落在机构的执行政策与场所比较表里，而不是落在监管拼装的参照价里。第二个对象是透明度：MiFID II 对场内挂牌设有前置透明要求，同时开了一族豁免——参照价豁免、协商成交豁免、大单豁免等——豁免簿里的流动性可见但不挂牌，暗量另有双顶帽子约束总量。把豁免簿当普通簿读深度，会把「看得见但不排队」当成「排得上队」。</p><p><span class="marginnote">「系统性内部化者」可以理解成「大号柜员」：一家券商用自己的库存持续接客户的单（像银行柜台用自己的钱换你的外汇），成交量大到一定程度就背上「持续双向报价」的义务。区别是柜台没有牌价表给你排队——它的报价只对眼前这一笔有效，这就是「对 SI 成交没有簿」的意思。</span></p><p><span class="marginnote">双顶帽子按滚动口径限制暗池份额，历史上多次触发、又被监管多次按市况暂停——暗侧容量不是自由变量，做市与暗侧执行策略要按帽子的预算周期排程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单换成欧洲版。其一，场所分类决定簿的形态：RM 与 MTF 挂牌撮合，SI 以自有账户对客户成交、对活跃品种有量化报价义务，两者的价差含义不同——对 SI 的成交没有簿可言。其二，逐场所归档透明度状态与豁免类型，研究里把「展示深度」按豁免与否分层报告。其三，合规侧的算法交易义务：算法要向监管报备，做测试、留 kill switch、持续做市要签做市协议——这是立项前置项，不是上线后补丁。其四，研究分拆：经纪研究不能默认用交易佣金支付，数据与研究的采购要单独走预算，投研成本结构因此与美国不同。其五，tick 按流动性分层给出，跨所比较价差时先对齐 tick 制。</p><p><span class="marginnote">「研究分拆」给个数字感觉：此前券商按交易额收万分之一佣金、附带送研究报告；分拆后交易佣金照付、研究再按份订阅，比如每年几十万欧元单独列支。小机构可能因此砍掉大半研究订阅，大机构则把研究成本从「交易成本」科目挪到「运营预算」——同一份研报，付费路径完全不同。</span></p>',10)),(i(),l(n,null,{default:a(()=>[r(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E5%AE%A2%E6%88%B7%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20BE%5B%22%E6%9C%80%E4%BD%B3%E6%89%A7%E8%A1%8C%EF%BC%9A%E4%B8%80%E5%88%87%E8%B6%B3%E5%A4%9F%E6%AD%A5%E9%AA%A4%22%5D%0A%20%20BE%20--%3E%20RM%5B%22%E5%8F%97%E7%9B%91%E7%AE%A1%E5%B8%82%E5%9C%BA%20RM%22%5D%0A%20%20BE%20--%3E%20MTF%5B%22MTF%22%5D%0A%20%20BE%20--%3E%20SI%5B%22%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%86%85%E9%83%A8%E5%8C%96%E8%80%85%20SI%22%5D%0A%20%20RM%20--%3E%20W%5B%22%E9%80%8F%E6%98%8E%E5%BA%A6%E8%B1%81%E5%85%8D%E7%B0%BF%22%5D%0A%20%20MTF%20--%3E%20W%0A%20%20W%20--%3E%20CAP%5B%22%E6%9A%97%E9%87%8F%E5%8F%8C%E9%A1%B6%E5%B8%BD%E5%AD%90%22%5D%0A%20%20BE%20--%3E%20REP%5B%22%E4%BA%A4%E6%98%93%E6%8A%A5%E5%91%8A%E4%B8%8E%E7%AE%97%E6%B3%95%E6%8A%A5%E5%A4%87%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"豁免是一笔交换：拿走前置透明，换来机构大单有处可去、执行概率上升；帽子再反过来防止暗份额无界增长。于是欧洲的「价差」要在三个状态上分别读——挂牌全透明、豁免簿可见、SI 无簿——混在一起平均会把结构差异抹平。SI 的量化报价义务把内部化准场所化：它有义务持续报价，但没有对手保护，最优结果仍由执行政策兜底。不这么做会错在哪：把美国的「最优价必然成交」直觉带进欧洲，会高估展示报价的可成交性；把豁免簿的挂单当排队深度，回测的成交概率会系统性偏乐观。",-1)),E[5]||(E[5]=e("p",null,"一笔机构大单如何在「透明度换执行概率」这笔交换里流动、帽子在哪里卡总量，这条回路回答的是「豁免簿的量为什么不能当排队深度」：",-1)),(i(),l(n,null,{default:a(()=>[r(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Big%5B%22%E6%9C%BA%E6%9E%84%E5%A4%A7%E5%8D%95%20%E4%B8%8D%E6%83%B3%E4%BA%AE%E6%98%8E%E5%85%A8%E9%83%A8%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20W%5B%22%E7%94%B3%E8%AF%B7%E8%B1%81%E5%85%8D%20%E5%A4%A7%E5%8D%95%E6%88%96%E5%8F%82%E7%85%A7%E4%BB%B7%22%5D%0A%20%20W%20--%3E%20WF%5B%22%E8%B1%81%E5%85%8D%E7%B0%BF%20%E5%8F%AF%E8%A7%81%E4%BD%86%E4%B8%8D%E6%8C%82%E7%89%8C%22%5D%0A%20%20WF%20--%3E%20Exec%5B%22%E4%B8%8E%E5%AF%B9%E6%89%8B%E5%8D%8F%E5%95%86%E6%88%90%E4%BA%A4%20%E6%89%A7%E8%A1%8C%E6%A6%82%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20Exec%20--%3E%20Share%5B%22%E6%9A%97%E9%87%8F%E5%8D%A0%E6%AF%94%E4%B8%8A%E5%8D%87%22%5D%0A%20%20Share%20--%3E%20Cap%7B%22%E8%A7%A6%E5%88%B0%E5%8F%8C%E9%A1%B6%E5%B8%BD%E5%AD%90%3F%22%7D%0A%20%20Cap%20--%20%22%E6%98%AF%22%20--%3E%20Back%5B%22%E6%BA%A2%E5%87%BA%E9%83%A8%E5%88%86%E5%9B%9E%E6%8C%82%E7%89%8C%E7%B0%BF%E6%8E%92%E9%98%9F%22%5D%0A%20%20Cap%20--%20%22%E5%90%A6%22%20--%3E%20Stay%5B%22%E7%95%99%E5%9C%A8%E8%B1%81%E5%85%8D%E4%BE%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">常见误区：初学者容易把豁免簿里的挂单量直接加进可成交深度。实际上豁免簿更像个「意向清单」——量看得见，但没有价格时间优先的排队保护，你的单来了对方可以不接。回测里若按排队深度算成交概率，会系统性高估能吃到多少量。</span></p><p>与上一课对照的机制价值在于：两条路线对同一份订单流给出不同的可执行集——美国的保护覆盖价格，欧洲的义务约束过程；策略迁移时，重新校准的正是这个「执行结果由谁保证」的假设。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>欧洲没有统一的合并磁带，跨所比较要自建包络，而且这个包络没有订单保护的法律含义——<a href="/quant/market-fragmentation">市场分割与 NBBO</a> 对「自建最优」的警告在这里加倍成立。英国脱欧后形成两个监管区，同一家机构在两侧要分别报备，场所格局与流动性格局都被重新切过。磁带与上市规则的修订在滚动落地，清单要按当期文本重读；结算周期等后链差异留到清算结算课统一写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧洲的秩序来自行为义务：中介的最佳执行「足够步骤」，不是机械的订单保护。</li><li>场所三分：RM、MTF、SI；SI 有量化报价义务但无簿，成交口径完全不同。</li><li>透明度豁免与大单、参照价、协商豁免是流动性形态的一部分，深度必须分层读。</li><li>算法报备、测试、kill switch 与研究分拆是立项前置合规项。</li><li>自建跨所包络没有保护含义，脱欧后的两个监管区要分开处理。</li><li>出处：MiFID II / MiFIR 公开文本；Foucault, Pagano and Röell, <em>Market Liquidity: Theory, Evidence, and Policy</em>, 2013。</li></ul>',6))])}const M=o(p,[["render",D]]);export{I as __pageData,M as default};
